import{z as i,x as A,o as B,c as d,q as t,j as s,D as r,d as E,s as o,S as l,b as e}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"Cerf–Kahn 互联","description":"","frontmatter":{"title":"Cerf–Kahn 互联","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/cerf-kahn-tcp.md","filePath":"cs/cerf-kahn-tcp.md","lastUpdated":1791413859000}'),h={name:"cs/cerf-kahn-tcp.md"};function p(C,a,c,f,m,D){const n=A("Mermaid");return B(),d("div",null,[a[2]||(a[2]=t('<h1 id="cerf–kahn-互联" tabindex="-1">Cerf–Kahn 互联 <a class="header-anchor" href="#cerf–kahn-互联" aria-label="Permalink to &quot;Cerf–Kahn 互联&quot;">​</a></h1><div class="epigraph"><p>把各异的分组网用网关连起来，端到端提供进程间可靠字节流；网络只转发分组，不要求所有网同一。 </p><footer>—— Cerf and Kahn, A Protocol for Packet Network Intercommunication, IEEE Trans. Comm. 1974</footer></div><p><a href="/cs/lampson-protection">上一课</a>附录对照了逻辑时间。附录对照，不插入主干。主干已在<a href="/cs/layering-e2e">分层与端到端</a>、<a href="/cs/tcp-handshake">TCP 三次握手</a>、<a href="/cs/tcp-seq-rexmit">序号与重传</a>里用过互联与可靠流；这里对照 <strong>1974 原文的问题</strong>：ARPANET 与其他分组网如何互联，进程如何在网关上看到统一的可靠通信。不重做拥塞控制后来的加法。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>主干分层课取端到端原则；TCP 课取三次握手与窗口。1974 文的缺口是互联本身：不同 MTU、不同路由、网关做封装，主机上的协议给出可靠、有序的进程到进程通信。<span class="marginnote">「网关」用今天的话说就是路由器的前身：站在两个分组网交界处、负责转交并更换封装的盒子。它认地址、管转发，但不管你的数据丢没丢一个字节——查漏补缺是两端主机的活。这正是「网关转发、主机保证」六个字的分工。</span>当时 TCP 与 IP 尚未拆成后来的两层，但「网关转发、主机保证」已经在。主干<a href="/cs/ip-subnet">IP 编址</a>是后来的地址语言。</p><p><span class="marginnote">1974 年的 TCP 包含后来 IP 的部分职能。对照时不要把 RFC 791/793 的年份写回这篇论文。拥塞控制是 1980 年代后的主干课，不是 1974 年的章节。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>进程用端口一类的寻址；分组经网关进入另一网络。可靠性：序号、重传、窗口——主干序号课已展开。附录只对照原文把「互联」与「端到端可靠」写成同一份协议设想，以及为何不要求子网内部可靠。</p>',8)),(B(),s(l,null,{default:r(()=>[o(n,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20NETS%5B%22%E5%90%84%E5%BC%82%E5%88%86%E7%BB%84%E7%BD%91%22%5D%20--%3E%20GW%5B%22%E7%BD%91%E5%85%B3%22%5D%0A%20%20HOST%5B%22%E4%B8%BB%E6%9C%BA%E5%8D%8F%E8%AE%AE%22%5D%20--%3E%20REL%5B%22%E5%8F%AF%E9%9D%A0%E8%BF%9B%E7%A8%8B%E6%B5%81%22%5D%0A%20%20GW%20--%3E%20HOST%0A%20%20REL%20--%3E%20TRUNK%5B%22%E4%B8%BB%E5%B9%B2%3A%20%E5%88%86%E5%B1%82%20%2F%20TCP%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,[E("端到端把纠错与排序放在主机，子网可以只尽最大努力。"),e("span",{class:"marginnote"},"端到端原则可以类比寄一套盖章文件：邮局只承诺「尽力送达」，可能延误、可能湿损；真正保证对方拿到完整文件的是寄收双方——每页编号、缺页补寄。若让每个中转邮局核对文件完整性，家家都要留底、家家都可能出错，成本高还保不齐。把保证放到两端，中间最简，这就是端到端。"),E("这与 Shannon 信道编码不是一层：一个是比特噪声，一个是分组丢失与乱序。主干"),e("a",{href:"/cs/udp"},"UDP"),E("后来把不可靠暴露给应用，是同一架构上的选项。Cerf–Kahn 不处理 TLS，不处理 BGP 政策——那些是后课与主干后段。")],-1)),(B(),s(l,null,{default:r(()=>[o(n,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E5%8F%91%E9%80%81%E8%BF%9B%E7%A8%8B%E5%86%99%E5%AD%97%E8%8A%82%E6%B5%81%22%5D%20--%3E%20T%5B%22%E5%8F%91%E9%80%81%E4%B8%BB%E6%9C%BA%EF%BC%9A%E5%88%87%E6%AE%B5%E3%80%81%E7%BC%96%E5%8F%B7%E3%80%81%E5%BE%85%E9%87%8D%E4%BC%A0%22%5D%0A%20%20T%20--%3E%20G1%5B%22%E7%BD%91%E5%85%B3%201%EF%BC%9A%E6%8D%A2%E5%B0%81%E8%A3%85%EF%BC%8C%E5%8F%AA%E8%BD%AC%E5%8F%91%22%5D%0A%20%20G1%20--%3E%20G2%5B%22%E7%BD%91%E5%85%B3%202%EF%BC%9A%E5%8F%AA%E8%BD%AC%E5%8F%91%EF%BC%8C%E4%B8%8D%E4%BF%9D%E8%AF%81%E5%8F%AF%E9%9D%A0%22%5D%0A%20%20G2%20--%3E%20R%5B%22%E6%8E%A5%E6%94%B6%E4%B8%BB%E6%9C%BA%EF%BC%9A%E5%8E%BB%E9%87%8D%E3%80%81%E9%87%8D%E6%8E%92%E3%80%81%E7%B4%A2%E8%A6%81%E7%BC%BA%E5%A4%B1%E6%AE%B5%22%5D%0A%20%20R%20--%3E%20D%5B%22%E6%8E%A5%E6%94%B6%E8%BF%9B%E7%A8%8B%E8%AF%BB%E5%88%B0%E5%AE%8C%E6%95%B4%E6%9C%89%E5%BA%8F%E5%AD%97%E8%8A%82%E6%B5%81%22%5D%0A%20%20LOST%5B%22%E5%AD%90%E7%BD%91%E4%B8%A2%E5%8C%85%E6%88%96%E4%B9%B1%E5%BA%8F%22%5D%20-.-%3E%7C%22%E4%B8%AD%E9%97%B4%E4%B8%8D%E4%BF%AE%EF%BC%8C%E7%95%99%E7%BB%99%E4%B8%BB%E6%9C%BA%22%7C%20R%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=t('<h3 id="为何对照而不插入主干" tabindex="-1">为何对照而不插入主干 <a class="header-anchor" href="#为何对照而不插入主干" aria-label="Permalink to &quot;为何对照而不插入主干&quot;">​</a></h3><p>主干按层上课：帧、IP、路由、传输。把 1974 插在 DMA 之后当第一课网络，会跳过帧与 MAC。附录只对照互联思想的出处，以及 TCP 课已经取走的可靠流骨架。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把这篇写成「谁发明互联网」的法庭文件。下一篇对照 Codd 1970 如何把数据从文件布局里抽出来，那是数据库第一课的文献。</p><p>网关不是应用层代理：它改的是分组网之间的封装，不是 HTTP。主干防火墙与 TLS 终止是另一层盒子。<span class="marginnote">常见误区：把 1974 文的「网关」读成今天的应用网关或代理。前者的工作在分组层——拆开一个网的封装、换上另一个网的封装再转发，看不见内容；防火墙、TLS 终止这类「看得懂内容」的盒子是后来才出现的另一种角色，两者别混为一谈。</span></p><p>对照结束应回到主干<a href="/cs/layering-e2e">分层与端到端</a>与 TCP 课。1974 文不插入帧与 MAC 之前。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>附录对照 Cerf and Kahn 1974：网关互联 + 端到端可靠进程通信。</li><li>主干分层与 TCP 课已取用；IP/TCP 拆分与拥塞是后来。</li><li>不插入 MAC 课之前。</li><li>出处：Cerf and Kahn, <em>IEEE Trans. Comm.</em> 22(5), 1974。</li></ul>',8))])}const F=i(h,[["render",p]]);export{P as __pageData,F as default};
